#include "string.h"
size_t strlen(const char *жол_деректер) { const char *деректер_лауазым = жол_деректер; while (*деректер_лауазым) деректер_лауазым++; return деректер_лауазым - жол_деректер; }
int memcmp(const void *첫째값, const void *둘째값, size_t 개수) { const unsigned char *x_координатасы = 첫째값, *Y_түймешігі_координата = 둘째값; while (개수--) { if (*x_координатасы != *Y_түймешігі_координата) return (int)*x_координатасы - *Y_түймешігі_координата; x_координатасы++; Y_түймешігі_координата++; } return 0; }
void *memmove(void *тағайындау_деректер, const void *жол_деректер, size_t 개수) { unsigned char *x_координатасы = тағайындау_деректер; const unsigned char *Y_түймешігі_координата = жол_деректер; if (x_координатасы < Y_түймешігі_координата) { for (size_t 순번 = 0; 순번 < 개수; 순번++) x_координатасы[순번] = Y_түймешігі_координата[순번]; } else { while (개수) { 개수--; x_координатасы[개수] = Y_түймешігі_координата[개수]; } } return тағайындау_деректер; }
int strncmp(const char *첫째값, const char *둘째값, size_t 개수) { while (개수--) { unsigned char x_координатасы = *첫째값++, Y_түймешігі_координата = *둘째값++; if (x_координатасы != Y_түймешігі_координата) return (int)x_координатасы-Y_түймешігі_координата; if (!x_координатасы) return 0; } return 0; }
/* lwIP only uses this for small decimal interface numbers. */
long strtol(const char *жол_деректер, char **тоқтату_жылжыту, int Фон_мән) {
    const char *басы_жылжыту = жол_деректер; unsigned long мән = 0; int кодтау_мән = 1, 하나라도 = 0;
    while (*жол_деректер == ' ' || (*жол_деректер >= 9 && *жол_деректер <= 13)) жол_деректер++;
    if (*жол_деректер == '-' || *жол_деректер == '+') { if (*жол_деректер == '-') кодтау_мән = -1; жол_деректер++; }
    if (Фон_мән == 0) Фон_мән = 10;
    while (*жол_деректер >= '0' && *жол_деректер <= '9' && *жол_деректер - '0' < Фон_мән) {
        unsigned сан_мән = *жол_деректер++ - '0'; 하나라도 = 1;
        if (мән > (0x7ffffffffffffffful - сан_мән) / (unsigned)Фон_мән) мән = 0x7ffffffffffffffful;
        else мән = мән * Фон_мән + сан_мән;
    }
    if (тоқтату_жылжыту) *тоқтату_жылжыту = (char *)(하나라도 ? жол_деректер : басы_жылжыту); return кодтау_мән > 0 ? (long)мән : -(long)мән;
}
int atoi(const char *жол_деректер) { return (int)strtol(жол_деректер, 0, 10); }
